use std::{collections::BTreeMap,fs};
fn main(){let mut all=BTreeMap::<(usize,usize),(usize,usize,Vec<usize>)>::new();for l in fs::read_to_string("research/hec_residual_span_20261116/incidence-oracle/ROOTS.tsv").unwrap().lines().skip(1){let v:Vec<_>=l.split('\t').collect();assert_eq!(v.len(),6);let n=|j:usize|v[j].parse::<usize>().unwrap();let e=all.entry((n(0),n(1))).or_insert((n(2),0,vec![0;n(2)]));assert_eq!(e.0,n(2));let support:Vec<_>=v[5].split(',').collect();assert_eq!(support.len(),3);for p in support{let j=p.split(':').next().unwrap().parse::<usize>().unwrap();e.2[j]+=1;}e.1+=1;}
assert_eq!(all.len(),6);println!("p\tsm\tcolumns\trows\tcore_size\ttop_incidence_sum\toptimistic_scan_gain_upper_bound");for((p,sm),(r,m,mut d))in all{assert_eq!(d.iter().sum::<usize>(),3*m);d.sort_unstable_by(|a,b|b.cmp(a));let mut s=0;let mut max=0f64;for(b,x)in d.iter().enumerate(){s+=x;let b=b+1;let bound=(r as f64/b as f64).min((r*s)as f64/(b*m)as f64);max=max.max(bound);println!("{p}\t{sm}\t{r}\t{m}\t{b}\t{s}\t{bound:.9}");}eprintln!("p={p} sm={sm} rows={m} columns={r} max_over_all_cuts={max:.9} tenfold_incidence_case={}",max>=10.0);}eprintln!("all_cuts_reported=true total_incidence_identity=true no_selection_cost_or_performance_claim=true");}
